/**
 ******************************************************************************
 * @file    fx_render.h
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) added the carry, so a stopped effect file can be made again from the middle (30 Oct 2026, with an AI coding assistant).
 * @brief   Effect-file renderer: the old live effect chain, run offline.
 *
 * What it does: turns the samples of a recording into the samples of its
 * effect file (for example FX/ECHO/REC05.WAV). Until 29 Oct 2026 TomTask
 * applied the effect live, inside every 4 ms DMA half, which slowed the
 * whole toy down. Now the effect file is made ahead of time with the same
 * chain, so it sounds as the live effect did (Echo now repeats after 240 ms
 * instead of 120 ms, as asked):
 *
 *     32 kHz recording:  each 64-sample block -> 2:3 upsampler (96 samples
 *                        at 48 kHz) -> AudioEffects_ProcessBlock on 64,
 *                        then on 32 samples
 *     48 kHz file:       each 64-sample block -> AudioEffects_ProcessBlock
 *
 * The output is always 48 kHz mono. The host tests check it sample for
 * sample against a copy of the old live chain's upsampler and effect loop,
 * run with today's effects.
 *
 * Who runs it: FxRenderTask (Core/Src/tom_fx_render.c), one chunk of up to
 * 512 source samples per request from JackStorageTask. Pure: no RTOS, no
 * HAL, compiles on any host (tests: Tests/OutputChain/test_fx_render.c).
 *
 * Main steps for one effect file:
 *   1. FxRender_Begin(effect, source rate)   once, before the first chunk:
 *                                            the effect's history is cleared
 *                                            and the pitch presets are set
 *   2. FxRender_Process(chunk)               for every chunk, in order; the
 *                                            history carries on from chunk to
 *                                            chunk, so the file has no seams
 *   FxRender_OutputSamples() says how long the file will be, before it is
 *   made.
 *
 * Making a file again from the middle (the CARRY, at the end of this file):
 * Jack can stop an effect file half made and carry on later. If FxRenderTask
 * made another file in between, the effect's memory is gone, so Jack starts
 * the effect again a little earlier (the PRE-ROLL), throws that output away,
 * and FxRender_LoadCarry puts back the few numbers that never forget. For
 * Autotune, Pitch up, Pitch down and Robot the rest of the file is then the
 * same, sample for sample, as one made in one go. Echo and Reverb can be a
 * tiny bit off, far too little to hear (how much, and why: the end of this
 * file). Tests/OutputChain/test_fx_resume.c checks it for every effect.
 ******************************************************************************
 */
#ifndef FX_RENDER_H
#define FX_RENDER_H

#include <stdint.h>

#include "audio_effects.h"
#include "rate_adapter.h"

#define FX_RENDER_RATE_32K_HZ           32000U  /* a recording: upsampled 2:3 first, as TomTask did live */
#define FX_RENDER_RATE_48K_HZ           48000U  /* a 48 kHz file: no upsampler */
#define FX_RENDER_BLOCK_SAMPLES         64U     /* the live chain's block: one AudioBlock_t of Jack's */
#define FX_RENDER_UPSAMPLED_BLOCK_SAMPLES 96U   /* one 64-sample block after the 2:3 upsampler */

/** Everything one effect file needs while it is being made (about 23.3 KB). */
typedef struct
{
    AudioEffectsState effects;          /* the effect's own history (23 072 B) */
    RateAdapter2to3 upsampler;          /* 32 kHz -> 48 kHz, for a 32 kHz source */
    uint8_t source_is_32k;              /* 1 = upsample each block first; 0 = 48 kHz source */
    int16_t block_48k[FX_RENDER_UPSAMPLED_BLOCK_SAMPLES];   /* one upsampled block */
} FxRender;

/**
 * @brief Prepare a new effect file. Works on any FxRender, even one that is
 *        all zeros (FxRenderTask's lives in .bss and is never initialised).
 *
 * First the whole effect state is cleared to zeros, so nothing of the file
 * made before is left in it. Then the same set-up the live chain did:
 * AudioEffects_Init (pitch presets +7 / -7 semitones), then SetMode and
 * Reset, and the upsampler restarts at 0.
 *
 * @param render         Renderer state.
 * @param mode           The effect (AUTOTUNE .. REVERB).
 * @param source_rate_hz FX_RENDER_RATE_32K_HZ or FX_RENDER_RATE_48K_HZ.
 * @return OK; NULL_POINTER; INVALID_MODE; INVALID_PARAMETER for another rate.
 *         Nothing is changed unless it returns OK.
 */
AudioEffectsStatus FxRender_Begin(FxRender *render,
                                  AudioEffectMode mode,
                                  uint32_t source_rate_hz);

/**
 * @brief Make the next part of the effect file from the next n_in source
 *        samples.
 *
 * Send the source in order, in chunks that are whole 64-sample blocks,
 * except the source's last chunk, which may end with a shorter block. Then
 * the blocks fall exactly where the live chain's blocks fell, and the
 * output does not depend on the chunk size.
 *
 * If the effect reports an error for a part, that part is copied through
 * dry (unchanged), as the live chain did, and the first error is returned;
 * *n_out is valid either way.
 *
 * @param render  Renderer state, after FxRender_Begin.
 * @param in      n_in source samples (32 or 48 kHz, as given to Begin).
 * @param n_in    Number of source samples (0 does nothing).
 * @param out     Output buffer for the 48 kHz effect samples (not in).
 * @param out_cap Room in out, in samples.
 * @param n_out   Set to the number of samples written to out.
 * @return OK, or the first effect error (the output is still valid);
 *         NULL_POINTER; BUFFER_ALIAS (in == out); INVALID_LENGTH when
 *         out_cap < FxRender_OutputSamples(n_in): then nothing is written.
 */
AudioEffectsStatus FxRender_Process(FxRender *render,
                                    const int16_t *in,
                                    uint32_t n_in,
                                    int16_t *out,
                                    uint32_t out_cap,
                                    uint32_t *n_out);

/**
 * @brief How many 48 kHz samples a source of source_samples samples gives.
 *
 * 48 kHz: the same number. 32 kHz: 96 for every whole 64-sample block, and
 * (3 x rest) / 2 for a last, shorter block: 96 x (n / 64) + (3 x (n % 64)) / 2.
 * Jack uses this to know how long a complete effect file must be.
 *
 * @return The output length in samples, or 0 for any other rate.
 */
uint32_t FxRender_OutputSamples(uint32_t source_samples, uint32_t source_rate_hz);

/* ------------------------------------------------------------------------ */
/* TEAM CODE (written by Brendon, 30 Oct 2026): making a file again from    */
/* the middle (the pre-roll and the carry)                                  */
/* ------------------------------------------------------------------------ */
/*
 * Jack stopped an effect file at source sample R, and FxRenderTask has made
 * another file since, so the effect's memory is someone else's. To carry on
 * at R, Jack (PD5b_Jack/Application/fx_job.c, preroll_start) does this:
 *   1. FxRender_Begin, then FxRender_Process from an earlier point S up to
 *      R, and throws that output away (it is in the file already). This
 *      PRE-ROLL refills the effect's delay lines and pitch detector with
 *      the same sound a file made in one go had there.
 *   2. FxRender_LoadCarry with the carry saved at R (FxRenderTask returns
 *      the carry with every chunk, and Jack keeps the one at R), then
 *      carries on from R.
 * If S is 0 the effect has run from the very first sample, so its state is
 * already the one-go state and step 2 is skipped.
 *
 * The rule for S (all numbers in 48 kHz OUTPUT samples): the last multiple
 * of FX_RENDER_PREROLL_GRID_SAMPLES that is at least the effect's pre-roll
 * before R; 0 if there is none.
 *
 * Why the grid, 3072 output samples (64 ms): it is 2048 source samples at
 * 32 kHz and 3072 at 48 kHz, so S falls on a chunk edge at both rates. It is
 * also a multiple of 1024, the step of the pitch shifter's delay line and of
 * the pitch detector (one estimate per 1024 samples), so a rebuilt effect
 * makes those steps on the very samples a one-go file made them on.
 *
 * Why 64 ms for Autotune, Pitch up, Pitch down and Robot: their output
 * depends on at most the last 45 ms of input (the detector's 2048-sample
 * window, the 39 ms look-ahead, the shifter's 289-sample delay line). The
 * rest of their state is in the carry. Measured on recorded voices: 50 ms
 * or more of pre-roll gives identical files, 30 ms not always.
 *
 * Why 4 s for Echo and Reverb: their memory is all delay line (Echo's 23 KB),
 * too big to carry, so the pre-roll refills it. That makes them very nearly,
 * but not always exactly, the one-go file, because every delay-line slot is
 * rounded to a whole sample (int16) each time round:
 *   - Echo is never more than 1 off (of 32768). Each repeat keeps 30 %, so
 *     a difference in a slot shrinks to 30 % of itself, plus at most 1 for
 *     the rounding, every 240 ms. After 10 repeats (2.4 s) even the largest
 *     possible difference is down to 1, and a 4 s pre-roll gives 16. But a
 *     difference of 1 can stay 1 (0.3 more can tip the rounding either
 *     way), so on loud sound a rebuilt Echo is 1 off in a few samples at
 *     some resume points (7 % of them on one of the team's speech
 *     recordings), for up to about 1.3 s after R (measured).
 *   - Reverb is identical on sound (measured at every chunk edge of the
 *     team's voice recordings). But in a quiet stretch the int16 rounding
 *     in its comb filters keeps a tiny tail going for ever in the one-go
 *     file, and a rebuild whose pre-roll starts in that stretch does not
 *     have it. They then differ by a few units: measured up to 10 of 32768
 *     (about -70 dBFS; a measurement, not a proven limit), until about a
 *     second after the sound comes back, or to the end of a file that ends
 *     in silence.
 * A longer pre-roll only makes these rarer; only S = 0 (a restart) would
 * rule them out. Tests/OutputChain/test_fx_resume.c checks all of this.
 */
#define FX_RENDER_PREROLL_GRID_SAMPLES   3072U    /* S is a multiple of this (64 ms at 48 kHz) */
#define FX_RENDER_PREROLL_SHORT_SAMPLES  3072U    /* Autotune, Pitch up, Pitch down, Robot: >= 64 ms */
#define FX_RENDER_PREROLL_LONG_SAMPLES   192000U  /* Echo, Reverb: >= 4 s */
#define FX_RENDER_CARRY_BYTES            44U      /* one carry: a 4-byte label and up to 40 bytes of state */

/**
 * @brief Copy out what the effect never forgets (the CARRY), after a chunk.
 *
 * Per effect: Autotune 32 B (the shifter's grain phase and dry share, the
 * two newest pitch estimates, the held note and its ratio, the de-click
 * filter, the unvoiced count); Pitch up / down 8 B (the grain phase and the
 * gliding ratio); Robot 40 B (its whole state: the 80 Hz oscillator never
 * forgets); Echo and Reverb nothing (the pre-roll refills them). A 4-byte
 * label in front says it is a carry and of which effect. FxRenderTask calls
 * this after EVERY chunk, so Jack always has the carry of the point where
 * a file stopped. Only reads the renderer; the rest of carry is zeros.
 *
 * @param render Renderer state, after FxRender_Begin. NULL: carry is zeroed
 *               (no carry).
 * @param carry  FX_RENDER_CARRY_BYTES to fill.
 */
void FxRender_SaveCarry(const FxRender *render, uint8_t carry[FX_RENDER_CARRY_BYTES]);

/**
 * @brief Put a carry saved by FxRender_SaveCarry back (after the pre-roll).
 *
 * @param render Renderer state, begun with the SAME effect.
 * @param carry  FX_RENDER_CARRY_BYTES from FxRender_SaveCarry.
 * @return OK; NULL_POINTER; INVALID_PARAMETER when carry is not a carry
 *         (all zeros, for example) or is another effect's. Nothing is
 *         changed unless it returns OK.
 */
AudioEffectsStatus FxRender_LoadCarry(FxRender *render, const uint8_t carry[FX_RENDER_CARRY_BYTES]);

#endif
